namespace ghidra.app.plugin.core.analysis;

using ghidra.app.services;
using ghidra.app.util.bin.format.objc;
using ghidra.app.util.bin.format.objc.objc1;
using ghidra.app.util.bin.format.objc.objc1;
using ghidra.app.util.bin.format.objc.objc2;
using ghidra.app.util.bin.format.objc.objc2;
using ghidra.app.util.importer;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;

public class ObjcTypeMetadataAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "Objective-C Type Metadata Analyzer";
	private static readonly string DESCRIPTION = "Discovers Objective-C type metadata records.";

	private AbstractObjcTypeMetadata typeMetadata;

	public ObjcTypeMetadataAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setDefaultEnablement(true);
		setPriority(AnalysisPriority.FORMAT_ANALYSIS);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return Objc1Constants.isObjectiveC(program) || Objc2Constants.isObjectiveC2(program);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		if (typeMetadata != null) {
			return true;
		}
		try {
			if (Objc1Constants.isObjectiveC(program)) {
				typeMetadata = new Objc1TypeMetadata(program, monitor, log);
			}
			else if (Objc2Constants.isObjectiveC2(program)) {
				typeMetadata = new Objc2TypeMetadata(program, monitor, log);
			}
			if (typeMetadata != null) {
				typeMetadata.applyTo();
			}
			return true;
		}
		catch (CancelledException e) {
			throw e;
		}
		catch (Exception e) {
			return false;
		}
	}

	/* @Override */
	public void analysisEnded(Program program) {
		if (typeMetadata != null) {
			typeMetadata.close();
			typeMetadata = null;
		}
	}
}
